/* -------------------------------------------------------------------------- */
/*  Helpers                                                                    */
/* -------------------------------------------------------------------------- */

// Deep-merge `override` onto a copy of `base`.
//  - Objects: keys are merged recursively; keys present only in override are kept.
//  - Arrays:  override replaces the whole array (the admin manages full lists).
//  - Primitives: override wins when defined.
function mergeDefaults(base, override) {
  if (Array.isArray(base)) {
    if (Array.isArray(override)) return override.map(v => mergeDefaults(v, undefined));
    return base.map(v => mergeDefaults(v, undefined));
  }
  if (base && typeof base === 'object') {
    const out = {};
    Object.keys(base).forEach(k => {
      out[k] = mergeDefaults(base[k], override && typeof override === 'object' ? override[k] : undefined);
    });
    if (override && typeof override === 'object' && !Array.isArray(override)) {
      Object.keys(override).forEach(k => {
        if (!(k in out)) out[k] = clone(override[k]);
      });
    }
    return out;
  }
  return override !== undefined ? override : base;
}

function clone(v) {
  return v == null ? v : JSON.parse(JSON.stringify(v));
}

// One-time shape migrations for content saved by older versions of the site.
function migrateData(data, raw) {
  raw = raw || {};
  const c = raw.contact || {};
  const rawFooterSocials = raw.footer && raw.footer.socials;
  const hadFlatSocials = c.facebook || c.twitter || c.instagram || c.linkedin;
  if (hadFlatSocials && !Array.isArray(rawFooterSocials)) {
    const out = [];
    if (c.facebook)  out.push({ id: 'soc_fb', label: 'Facebook',    icon: 'lni-facebook-original',  url: c.facebook });
    if (c.twitter)   out.push({ id: 'soc_tw', label: 'Twitter / X', icon: 'lni-twitter-original',   url: c.twitter });
    if (c.instagram) out.push({ id: 'soc_ig', label: 'Instagram',   icon: 'lni-instagram-original', url: c.instagram });
    if (c.linkedin)  out.push({ id: 'soc_in', label: 'LinkedIn',    icon: 'lni-linkedin-original',  url: c.linkedin });
    if (out.length) data.footer.socials = out;
  }
  if (raw.yknot && raw.yknot.active === false && (!raw.sections || raw.sections.yknot === undefined)) {
    data.sections.yknot = false;
  }
}

// The published baseline for every visitor: built-in defaults with content.js applied on top.
const TBP_PUBLISHED_BASE = (typeof window !== 'undefined'
  && window.TBP_PUBLISHED_CONTENT
  && typeof window.TBP_PUBLISHED_CONTENT === 'object')
  ? window.TBP_PUBLISHED_CONTENT
  : {};

class SiteDataManager {
  constructor() {
    this._published = mergeDefaults(DEFAULT_SITE_DATA, TBP_PUBLISHED_BASE);
    this._recompute();
    this.setupListeners();
  }

  _readDraft() {
    try {
      const s = localStorage.getItem(TBP_STORAGE_KEY);
      return s ? JSON.parse(s) : null;
    } catch (e) {
      return null;
    }
  }

  _recompute() {
    const draft = this._readDraft();
    const merged = draft ? mergeDefaults(this._published, draft) : clone(this._published);
    migrateData(merged, draft || {});
    this._cache = merged;
    this._hasDraft = !!draft;
  }

  /** The effective content the site should render right now. */
  getData() {
    return clone(this._cache);
  }

  /** True when this browser has unpublished Admin edits stored locally. */
  hasLocalDraft() {
    return !!this._hasDraft;
  }

  /** Save Admin edits as this browser's local draft. */
  saveData(data, notify = true) {
    try {
      localStorage.setItem(TBP_STORAGE_KEY, JSON.stringify(data));
      const merged = mergeDefaults(DEFAULT_SITE_DATA, data);
      migrateData(merged, data);
      this._cache = merged;
      this._hasDraft = true;
      if (notify) {
        window.dispatchEvent(new CustomEvent('tbp_data_updated', { detail: this._cache }));
      }
      return { success: true };
    } catch (e) {
      console.error('Error saving site data to localStorage', e);
      return { success: false, error: e.message };
    }
  }

  /** Throw away the local draft and show exactly what is published. */
  clearDraft() {
    try {
      localStorage.removeItem(TBP_STORAGE_KEY);
    } catch (e) { /* ignore */ }
    this._recompute();
    window.dispatchEvent(new CustomEvent('tbp_data_updated', { detail: this._cache }));
    return this.getData();
  }

  /** Alias kept for the Admin "revert" button. */
  resetToDefault() {
    return this.clearDraft();
  }

  /** Plain JSON snapshot (for personal backups). */
  exportDataJson() {
    return JSON.stringify(this.getData(), null, 2);
  }

  /** The content.js file to commit in order to publish the current content. */
  exportPublishFile() {
    const banner = [
      '/**',
      ' * The Bandhan Project (tbp;) — PUBLISHED WEBSITE CONTENT',
      ' * ---------------------------------------------------------------',
      ' * Auto-generated by the Admin panel. Do NOT edit by hand.',
      ' * To publish changes: make edits in admin.html, click',
      ' * "Download content.js for publishing", then replace',
      ' * assets/js/content.js with this file and deploy.',
      ' * Generated: ' + new Date().toISOString(),
      ' */',
      '',
      'window.TBP_PUBLISHED_CONTENT = '
    ].join('\n');
    return banner + JSON.stringify(this.getData(), null, 2) + ';\n';
  }

  importDataJson(jsonString) {
    try {
      const parsed = JSON.parse(jsonString);
      if (parsed && typeof parsed === 'object') {
        this.saveData(parsed, true);
        return { success: true };
      }
      return { success: false, error: 'Invalid data format' };
    } catch (e) {
      return { success: false, error: e.message };
    }
  }

  isAdminAuthenticated() {
    try {
      return sessionStorage.getItem(TBP_ADMIN_AUTH_KEY) === 'true';
    } catch (e) {
      return false;
    }
  }

  loginAdmin(enteredPassword) {
    const correctPassword = (this.getData().admin && this.getData().admin.password) || 'admin123';
    if (enteredPassword === correctPassword) {
      try { sessionStorage.setItem(TBP_ADMIN_AUTH_KEY, 'true'); } catch (e) { /* ignore */ }
      return true;
    }
    return false;
  }

  logoutAdmin() {
    try { sessionStorage.removeItem(TBP_ADMIN_AUTH_KEY); } catch (e) { /* ignore */ }
  }

  setAdminPassword(newPassword) {
    const data = this.getData();
    data.admin = data.admin || {};
    data.admin.password = newPassword;
    this.saveData(data);
  }

  setupListeners() {
    window.addEventListener('storage', (event) => {
      if (event.key === TBP_STORAGE_KEY) {
        this._recompute();
        window.dispatchEvent(new CustomEvent('tbp_data_updated', { detail: this._cache }));
      }
    });
  }
}

// Global instance
window.TBP_DATA = new SiteDataManager();

// Exposed for tooling (the build script that generates content.js) and console debugging.
window.TBP_DEFAULT_CONTENT = DEFAULT_SITE_DATA;
